function renderExamples(){
 const box=$('examples'),list=$('exampleList');
 list.replaceChildren();
 const source=current.sourcePhrase||current;
 box.classList.add('hidden');
 if(current.sourcePhrase)return;
 const sentences=EXAMPLE_SENTENCES[source.id];
 (sentences||EXAMPLE_PROMPTS[source.id]||[]).forEach((pair,index)=>{
  const example=sentences?
   {id:'example-'+source.id+'-'+index,es:pair[0],ru:pair[1],region:source.region,category:source.category,context:'Пример употребления выражения.',exampleKind:current.kind,sourcePhrase:source}:
   {id:'example-'+source.id+'-'+index,es:source.es,ru:source.ru,scenarioEs:pair[0],scenarioRu:pair[1],region:source.region,category:source.category,context:'Ответ в конкретной ситуации.',exampleKind:current.kind,sourcePhrase:source};
  const button=document.createElement('button');
  button.type='button';button.className='example-button';
  const spanish=document.createElement('strong');
  spanish.textContent=sentences?example.es:'— '+pair[0]+'\n— '+source.es;
  const russian=document.createElement('small');
  russian.textContent=sentences?example.ru:'— '+pair[1]+'\n— '+source.ru;
  button.append(spanish,russian);
  button.onclick=()=>{queue.splice(position,0,example);render();window.scrollTo({top:0,behavior:'smooth'})};
  list.append(button);
 });
}
