function setupMicButton(){
 const btn=$('mic');
 const holdDelay=350;
 let pointerId=null;
 function press(e){
  if(btn.disabled||micState==='recording'||micStarting||micHoldTimer)return;
  if(e.pointerType==='mouse'&&e.button!==0)return;
  pointerId=e.pointerId;
  micHoldTimer=setTimeout(()=>{
   micHoldTimer=null;micHoldActive=true;micIgnoreClickUntil=Date.now()+900;
   mic();
  },holdDelay);
 }
 function release(e){
  if(pointerId===null||e.pointerId!==pointerId)return;
  pointerId=null;
  if(micHoldTimer){clearTimeout(micHoldTimer);micHoldTimer=null;return}
  if(micHoldActive){
   micHoldActive=false;micIgnoreClickUntil=Date.now()+900;stopMic();
  }
 }
 if(window.PointerEvent){
  btn.addEventListener('pointerdown',press);
  document.addEventListener('pointerup',release);
  document.addEventListener('pointercancel',release);
 }else{
  let touchId=null;
  btn.addEventListener('touchstart',e=>{
   if(btn.disabled||micState==='recording'||micStarting||micHoldTimer)return;
   touchId=e.changedTouches[0].identifier;
   micHoldTimer=setTimeout(()=>{
    micHoldTimer=null;micHoldActive=true;micIgnoreClickUntil=Date.now()+900;mic();
   },holdDelay);
  },{passive:true});
  function touchRelease(e){
   if(touchId===null||![...e.changedTouches].some(t=>t.identifier===touchId))return;
   touchId=null;
   if(micHoldTimer){clearTimeout(micHoldTimer);micHoldTimer=null;return}
   if(micHoldActive){micHoldActive=false;micIgnoreClickUntil=Date.now()+900;stopMic()}
  }
  document.addEventListener('touchend',touchRelease);
  document.addEventListener('touchcancel',touchRelease);
 }
 btn.addEventListener('click',e=>{
  if(Date.now()<micIgnoreClickUntil){e.preventDefault();return}
  mic();
 });
}
function dictionary(){let term=normalize($('search').value),cat=$('catFilter').value,reg=$('regionFilter').value,f=$('listFilter').value;let items=all().filter(p=>(!term||normalize(p.es+' '+p.ru).includes(term))&&(!cat||p.category===cat)&&(!reg||p.region.includes(reg))&&(f==='all'||f==='favorite'&&state.favorites[p.id]||f==='hard'&&card(p.id).hard));let el=$('entries');el.replaceChildren();items.forEach(p=>{let d=document.createElement('div');d.className='phrase';let strong=document.createElement('strong');strong.textContent=p.es;let sub=document.createElement('small');sub.textContent=p.ru+' · '+p.region.join(', ')+' · '+p.category;let b=document.createElement('button');b.textContent=state.favorites[p.id]?'♥ В избранном':'♡ В избранное';b.onclick=()=>{state.favorites[p.id]=!state.favorites[p.id];save();dictionary()};let h=document.createElement('button');h.textContent=card(p.id).hard?'★ Сложная':'☆ Сложная';h.onclick=()=>{let c=card(p.id);c.hard=!c.hard;state.cards[p.id]=c;save();dictionary()};d.append(strong,sub,document.createElement('br'),b,h);el.append(d)});if(!items.length)el.textContent='Ничего не найдено'}function populateVoices(){if(!('speechSynthesis'in window))return;voices=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('es'));let old=$('voice').value;$('voice').replaceChildren(new Option('Автоматически (es)',''));voices.forEach(v=>$('voice').add(new Option(v.name+' · '+v.lang,v.name)));$('voice').value=old}async function init(){try{let r=await fetch('phrases.json');if(!r.ok)throw Error('HTTP '+r.status);phrases=await r.json()}catch(e){$('count').textContent='Не удалось загрузить словарь: '+e.message;return}let categories=[...new Set(phrases.map(x=>x.category))];categories.forEach(x=>$('catFilter').add(new Option(x,x)));$('start').onclick=start;$('reviewStart').onclick=()=>startReview();$('answer').addEventListener('input',()=>{if(wasRecognized)recognizedEdited=true});$('historyMore').onclick=()=>{historyVisible+=20;renderHistory()};$('back').onclick=()=>page('home');$('check').onclick=checkRecording;$('reveal').onclick=()=>check(true);$('again').onclick=()=>advance(false);$('know').onclick=()=>advance(true);setupMicButton();$('play').onclick=()=>speak();$('slow').onclick=()=>speak(.5);['search','catFilter','regionFilter','listFilter'].forEach(id=>$(id).addEventListener('input',dictionary));$('add').onclick=()=>{let es=$('newEs').value.trim(),ru=$('newRu').value.trim();if(!es||!ru)return;state.custom.push({id:'custom-'+Date.now(),es,ru,region:['LATAM'],category:'Мои фразы',rough:0,context:'Добавлено пользователем'});save();$('newEs').value=$('newRu').value='';dictionary()};$('export').onclick=()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='latam-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)};$('import').onchange=async e=>{try{let s=JSON.parse(await e.target.files[0].text());if(!s||typeof s!=='object'||!s.cards||!s.favorites||!Array.isArray(s.custom))throw Error('Неверный формат');state={...state,...s};if(!Array.isArray(state.history))state.history=[];save();stats();alert('Прогресс импортирован')}catch(err){alert('Не удалось импортировать: '+err.message)}};let savedTheme=null;try{savedTheme=localStorage.getItem('latam-theme')}catch{}$('light').checked=savedTheme!=='dark';document.body.classList.toggle('light',$('light').checked);$('light').onchange=e=>{document.body.classList.toggle('light',e.target.checked);try{localStorage.setItem('latam-theme',e.target.checked?'light':'dark')}catch{}};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));if('speechSynthesis'in window){populateVoices();speechSynthesis.onvoiceschanged=populateVoices}if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});stats()}init();
